implementation:
AutocompleteMatch convert_scored_history_match_to_autocomplete_match(const ScoredHistoryMatch* history_match, int score) {
    AutocompleteMatch match;

    // Initialize the match structure to zero to ensure all fields are set.
    memset(&match, 0, sizeof(match));

    // Validate the input pointer.
    if (!history_match) {
        return match;
    }

    // Copy URL and title from history_match, ensuring they are null-terminated.
    size_t url_len = strlen(history_match->url);
    size_t title_len = strlen(history_match->title);

    // Ensure the destination buffers are large enough.
    size_t max_url_len = sizeof(match.url) - 1;
    size_t max_title_len = sizeof(match.title) - 1;

    // Truncate if necessary.
    size_t url_copy_len = (url_len < max_url_len) ? url_len : max_url_len;
    size_t title_copy_len = (title_len < max_title_len) ? title_len : max_title_len;

    strncpy(match.url, history_match->url, url_copy_len);
    match.url[url_copy_len] = '\0';

    strncpy(match.title, history_match->title, title_copy_len);
    match.title[title_copy_len] = '\0';

    // Set the score.
    match.score = score;

    // Handle inline autocomplete offsets if applicable.
    if (history_match->inline_autocomplete_offset >= 0 && 
        (size_t)history_match->inline_autocomplete_offset < url_len) {
        match.inline_autocomplete_offset = history_match->inline_autocomplete_offset;
    }

    return match;
}
